head.script:
scwin.ibx_openPopup2_onclick = function(e) {
	if(WebSquare._xv !== "SP5"){requires("uiplugin.popup");}
	var opts = {
		"id": "popup_atag",
		"type": "wframePopup",
		"width": "700px",
		"height": "250px",
		"top": 450,
		"left": 150,
		"popupName": "Popup_웹접근성",
		"useATagBtn": true
	};
	scwin.$w.openPopup("/sample/common_link/p_popup_useATagBtn_WEFF-403_(WSQ-3772)_sub.xml", opts);
};
